SELECT id, store_id, model_id, schema_version, dsl_text, status, description,
       tenant_id, create_time, created_by, update_time, updated_by, is_deleted
FROM fga_authorization_model
WHERE store_id = #{storeId}
  AND model_id = #{modelId}
  AND is_deleted = 0

SELECT id, store_id, model_id, schema_version, dsl_text, status, description,
       tenant_id, create_time, created_by, update_time, updated_by, is_deleted
FROM fga_authorization_model
WHERE store_id = #{storeId}
  AND is_deleted = 0

  AND status = #{status}


  AND model_id = #{pageToken}

ORDER BY create_time DESC
LIMIT #{pageSize}
